import { describe, expect, it } from "vitest";
import {
  mergeUsagePricingBucket,
  projectUsagePricingContext,
} from "../src/lib/usage-pricing-context.js";

/**
 * Request-level cache/long-context pricing contract.
 *
 * mergeUsagePricingBucket folds per-request token usage into a bounded set of
 * aggregate price buckets, keeping requests that are subject to different
 * multipliers (long-context > threshold, service tier, regional processing)
 * in separate buckets. Token counts that a per-request contract must price
 * differently — fresh input vs cache reads — are accumulated separately so
 * downstream pricing can apply the cache multiplier per request.
 */

const THRESHOLD = 272000;

// entry must be a documented openai model for bucket projection to apply.
const makeEntry = () => ({ provider: "openai", model: "gpt-6-sol" });

// Sort buckets by their retained requestInputTokens so assertions are stable.
const byRequestTokens = (a, b) => a.requestInputTokens - b.requestInputTokens;

describe("mergeUsagePricingBucket — request-level cache & long-context contract", () => {
  it("splits on the strict long-context boundary (> 272000)", () => {
    const entry = makeEntry();
    // promptTokens = inputTokens (no cache). Exactly at the threshold is NOT
    // long; one token over is long.
    mergeUsagePricingBucket(entry, { inputTokens: THRESHOLD, outputTokens: 1 });
    mergeUsagePricingBucket(entry, {
      inputTokens: THRESHOLD + 1,
      outputTokens: 1,
    });
    expect(entry.pricingBuckets).toHaveLength(2);
    const [atBoundary, overBoundary] = entry.pricingBuckets.slice().sort(byRequestTokens);
    expect(atBoundary.requestInputTokens).toBe(THRESHOLD);
    expect(atBoundary.inputTokens).toBe(THRESHOLD);
    expect(overBoundary.requestInputTokens).toBe(THRESHOLD + 1);
    expect(overBoundary.inputTokens).toBe(THRESHOLD + 1);
  });

  it("keeps same-total requests with different cache/long distributions in separate buckets", () => {
    const entry = makeEntry();
    // Both requests have the same total tokens (272000 input-side) but differ
    // in how they cross the long-context threshold and in cache composition.
    mergeUsagePricingBucket(entry, {
      inputTokens: 200000,
      cacheReadTokens: 72000,
      requestInputTokens: THRESHOLD, // not long
      outputTokens: 0,
    });
    mergeUsagePricingBucket(entry, {
      inputTokens: 272000,
      cacheReadTokens: 0,
      requestInputTokens: THRESHOLD + 1, // long
      outputTokens: 0,
    });
    expect(entry.pricingBuckets).toHaveLength(2);
    const sorted = entry.pricingBuckets.slice().sort(byRequestTokens);
    // Per-request contract: fresh input vs cache read are preserved separately.
    expect(sorted[0]).toMatchObject({
      requestInputTokens: THRESHOLD,
      inputTokens: 200000,
      cacheReadTokens: 72000,
      calls: 1,
    });
    expect(sorted[1]).toMatchObject({
      requestInputTokens: THRESHOLD + 1,
      inputTokens: 272000,
      cacheReadTokens: 0,
      calls: 1,
    });
  });

  it("merges same-total requests when the long-context distribution matches (negative)", () => {
    const entry = makeEntry();
    // Same total tokens (272000) and the same long-context flag: cache/input
    // split still accumulates separately, but into a single bucket.
    mergeUsagePricingBucket(entry, {
      inputTokens: 200000,
      cacheReadTokens: 72000,
      requestInputTokens: THRESHOLD + 1,
    });
    mergeUsagePricingBucket(entry, {
      inputTokens: 272000,
      cacheReadTokens: 0,
      requestInputTokens: THRESHOLD + 1,
    });
    expect(entry.pricingBuckets).toHaveLength(1);
    expect(entry.pricingBuckets[0]).toMatchObject({
      inputTokens: 472000,
      cacheReadTokens: 72000,
      totalTokens: 472000,
      calls: 2,
    });
  });

  it("lets requestInputTokens override the computed cache-inclusive prompt length", () => {
    const entry = makeEntry();
    // Computed input+cache far exceeds the threshold, but the explicit
    // requestInputTokens keeps it non-long.
    mergeUsagePricingBucket(entry, {
      inputTokens: 300000,
      cacheReadTokens: 50000,
      requestInputTokens: 100000,
      outputTokens: 10,
    });
    expect(entry.pricingBuckets).toHaveLength(1);
    expect(entry.pricingBuckets[0].requestInputTokens).toBe(100000);
    // Negative control: without requestInputTokens the computed length applies.
    const computed = makeEntry();
    mergeUsagePricingBucket(computed, {
      inputTokens: 300000,
      cacheReadTokens: 50000,
      outputTokens: 10,
    });
    expect(computed.pricingBuckets[0].requestInputTokens).toBe(350000);
    // 350000 > 272000 => long, whereas 100000 is not long.
    expect(entry.pricingBuckets[0].requestInputTokens > THRESHOLD).toBe(false);
    expect(computed.pricingBuckets[0].requestInputTokens > THRESHOLD).toBe(true);
  });

  it("splits buckets by service tier and projects unknown tiers safely", () => {
    const entry = makeEntry();
    mergeUsagePricingBucket(entry, { inputTokens: 1000, serviceTier: "fast" });
    mergeUsagePricingBucket(entry, { inputTokens: 1000, serviceTier: "flex" });
    expect(entry.pricingBuckets).toHaveLength(2);
    expect(entry.pricingBuckets.map((b) => b.serviceTier).sort()).toEqual([
      "fast",
      "flex",
    ]);
    // Non-documented tier is projected to "unknown", not dropped or mispriced.
    expect(
      projectUsagePricingContext({ service_tier: "constructor" }).service_tier,
    ).toBe("unknown");
    expect(
      projectUsagePricingContext({ serviceTier: "fast" }).service_tier,
    ).toBe("fast");
  });

  it("splits buckets by regional processing and rejects a non-boolean value", () => {
    const entry = makeEntry();
    mergeUsagePricingBucket(entry, {
      inputTokens: 1000,
      regionalProcessing: true,
    });
    mergeUsagePricingBucket(entry, {
      inputTokens: 1000,
      regionalProcessing: false,
    });
    expect(entry.pricingBuckets).toHaveLength(2);
    expect(
      entry.pricingBuckets.map((b) => b.regionalProcessing).sort(),
    ).toEqual([false, true]);
    expect(() =>
      projectUsagePricingContext({ regional_processing: "yes" }),
    ).toThrow(/must be boolean/);
  });
});

import { describe, it, expect, afterEach } from "vitest";
import {
  extractUsage,
  aggregateUsage,
  sessionUsage,
  allSessionsUsage,
  _deps,
} from "../../src/lib/session-usage.js";

const usageEvent = (model, input, output) => ({
  type: "token_usage",
  data: { model, usage: { input_tokens: input, output_tokens: output } },
});

describe("session-usage", () => {
  describe("extractUsage", () => {
    it("reads a token_usage event", () => {
      const u = extractUsage({
        type: "token_usage",
        timestamp: 1,
        data: {
          provider: "anthropic",
          model: "claude-opus-4-6",
          usage: { input_tokens: 100, output_tokens: 50 },
        },
      });
      expect(u).toEqual({
        provider: "anthropic",
        model: "claude-opus-4-6",
        inputTokens: 100,
        outputTokens: 50,
        totalTokens: 150,
        cacheReadTokens: 0,
        cacheCreationTokens: 0,
        timestamp: 1,
      });
    });

    it("reads usage embedded in assistant_message", () => {
      const u = extractUsage({
        type: "assistant_message",
        timestamp: 2,
        data: {
          content: "...",
          usage: { prompt_tokens: 40, completion_tokens: 20, total_tokens: 60 },
          model: "gpt-4o",
        },
      });
      expect(u).toMatchObject({
        model: "gpt-4o",
        inputTokens: 40,
        outputTokens: 20,
        totalTokens: 60,
      });
    });

    it("returns null for events without usage", () => {
      expect(extractUsage({ type: "user_message", data: {} })).toBeNull();
      expect(
        extractUsage({ type: "assistant_message", data: { content: "hi" } }),
      ).toBeNull();
    });

    it("returns null for unknown event types", () => {
      expect(
        extractUsage({
          type: "tool_call",
          data: { usage: { input_tokens: 10 } },
        }),
      ).toBeNull();
    });

    it("returns null when all counts are zero", () => {
      expect(
        extractUsage({
          type: "token_usage",
          data: { usage: { input_tokens: 0, output_tokens: 0 } },
        }),
      ).toBeNull();
    });
  });

  describe("aggregateUsage", () => {
    it("rolls up total + per-model", () => {
      const agg = aggregateUsage([
        {
          type: "token_usage",
          data: {
            provider: "anthropic",
            model: "opus",
            usage: { input_tokens: 100, output_tokens: 50 },
          },
        },
        {
          type: "token_usage",
          data: {
            provider: "anthropic",
            model: "opus",
            usage: { input_tokens: 30, output_tokens: 10 },
          },
        },
        {
          type: "token_usage",
          data: {
            provider: "openai",
            model: "gpt-4o",
            usage: { input_tokens: 20, output_tokens: 5 },
          },
        },
      ]);
      expect(agg.total).toEqual({
        inputTokens: 150,
        outputTokens: 65,
        totalTokens: 215,
        cacheReadTokens: 0,
        cacheCreationTokens: 0,
        calls: 3,
      });
      expect(agg.byModel).toHaveLength(2);
      expect(agg.byModel[0]).toMatchObject({
        provider: "anthropic",
        model: "opus",
        inputTokens: 130,
        outputTokens: 60,
        calls: 2,
      });
      expect(agg.byModel[1]).toMatchObject({
        provider: "openai",
        model: "gpt-4o",
        inputTokens: 20,
        outputTokens: 5,
        calls: 1,
      });
    });

    it("ignores events without usage", () => {
      const agg = aggregateUsage([
        { type: "user_message", data: { content: "hi" } },
        { type: "tool_call", data: { tool: "read_file", args: {} } },
      ]);
      expect(agg.total.calls).toBe(0);
      expect(agg.byModel).toEqual([]);
    });

    it("handles empty + nullish input", () => {
      expect(aggregateUsage([]).total.calls).toBe(0);
      expect(aggregateUsage(null).total.calls).toBe(0);
    });

    it("sorts byModel descending by totalTokens", () => {
      const agg = aggregateUsage([
        {
          type: "token_usage",
          data: {
            model: "small",
            usage: { input_tokens: 1, output_tokens: 1 },
          },
        },
        {
          type: "token_usage",
          data: {
            model: "big",
            usage: { input_tokens: 500, output_tokens: 500 },
          },
        },
      ]);
      expect(agg.byModel[0].model).toBe("big");
      expect(agg.byModel[1].model).toBe("small");
    });
  });

  describe("allSessionsUsage (resilient roll-up)", () => {
    const origReadEvents = _deps.readEvents;
    const origListSessions = _deps.listJsonlSessions;
    afterEach(() => {
      _deps.readEvents = origReadEvents;
      _deps.listJsonlSessions = origListSessions;
    });

    it("aggregates across sessions and skips one that fails to read", () => {
      _deps.listJsonlSessions = () => [
        { id: "good-1" },
        { id: "bad" },
        { id: "good-2" },
      ];
      _deps.readEvents = (id) => {
        if (id === "bad") {
          throw Object.assign(new Error("EACCES"), { code: "EACCES" });
        }
        return [usageEvent("opus", 100, 50)];
      };

      const r = allSessionsUsage();
      expect(r.skipped).toBe(1); // the unreadable session didn't abort the rest
      expect(r.sessions).toHaveLength(2); // good-1 + good-2
      expect(r.total.calls).toBe(2);
      expect(r.total.totalTokens).toBe(300); // 2 × (100+50)
      expect(r.byModel[0]).toMatchObject({ model: "opus", calls: 2 });
    });

    it("reports zero skipped when every session reads cleanly", () => {
      _deps.listJsonlSessions = () => [{ id: "a" }, { id: "b" }];
      _deps.readEvents = () => [usageEvent("gpt-4o", 10, 5)];
      const r = allSessionsUsage();
      expect(r.skipped).toBe(0);
      expect(r.sessions).toHaveLength(2);
    });

    it("sessionUsage rolls up a single session via the injected reader", () => {
      _deps.readEvents = () => [
        usageEvent("opus", 100, 50),
        usageEvent("opus", 30, 10),
      ];
      const r = sessionUsage("s1");
      expect(r.sessionId).toBe("s1");
      expect(r.total.calls).toBe(2);
      expect(r.total.inputTokens).toBe(130);
    });
  });
});

